function validate([time]) {
  if (!Array.isArray(time) || time.length < 1 || time.length > 60000) return 'time needs 1 to 60000 songs.';
  if (time.some(v => !Number.isInteger(v) || v < 1 || v > 500)) return 'Each duration is a whole number from 1 to 500.';
  return null;
}

