function numPairsDivisibleBy60(time) {
  const count = new Array(60).fill(0);
  let pairs = 0;
  for (const duration of time) {
    const remainder = duration % 60;
    const complement = (60 - remainder) % 60;
    pairs += count[complement];
    count[remainder]++;
  }
  return pairs;
}

