function generate(rand, size) {
  const pick = (k) => Math.floor(rand() * k);
  const n = size === 'large' ? 2000 : 1 + pick(10);
  // Small inputs draw from a few remainders so that matching pairs are common.
  const remainders = size === 'large' ? null : Array.from({ length: 1 + pick(3) }, () => [0, 30, 10, 50, 20, 40, pick(60)][pick(7)]);
  if (remainders && rand() < 0.6) remainders.push((60 - remainders[0]) % 60);
  const time = Array.from({ length: n }, () => {
    if (!remainders || rand() < 0.15) return 1 + pick(500);
    const r = remainders[pick(remainders.length)];
    const base = r === 0 ? 60 : r;
    return base + 60 * pick(Math.floor((500 - base) / 60) + 1);
  });
  return [time];
}
